from pathlib import Path
import re
p=Path('caso001-rev01/index.html')
s=p.read_text()
if 'P2.12D.9 · CINEMATIC ACCUSATION' in s:
    raise SystemExit('D9 already applied')

css=r'''
/* P2.12D.9 · CINEMATIC ACCUSATION */
.accusationCinematic{padding:0;overflow:hidden;border-color:#713d34;background:#0d0b0a}.accHero{position:relative;padding:18px 20px;border-bottom:1px solid #553629;background:radial-gradient(circle at 85% 10%,rgba(129,35,31,.18),transparent 34%),linear-gradient(180deg,#1b1210,#0e0b0a)}.accHero:after{content:"ACUSACIÓN";position:absolute;right:13px;top:14px;border:3px solid rgba(166,47,42,.4);color:rgba(215,75,65,.52);padding:5px 8px;transform:rotate(-6deg);font-size:10px;letter-spacing:.14em;font-weight:950}.accKicker{font-size:8px;letter-spacing:.2em;color:#a9805d;font-weight:950}.accHero h2{font-family:Impact,'Arial Narrow',sans-serif;text-transform:uppercase;font-size:clamp(30px,5vw,46px);letter-spacing:.02em;margin:5px 0 5px;color:#f1dfcc}.accHero p{margin:0;color:#a99a8b;font-size:11px;line-height:1.5;max-width:720px}.accBody{padding:17px 18px 19px}.accProgress{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:15px}.accProgress span{border:1px solid #49372a;background:#12100e;padding:7px 6px;text-align:center;font-size:7px;letter-spacing:.09em;color:#776b5e}.accProgress span.done{border-color:#7b5830;color:#e2bd7a;background:#1c150e}.accAxis{margin-top:16px}.accAxis:first-of-type{margin-top:0}.accAxisHead{display:flex;justify-content:space-between;align-items:end;gap:10px;padding-bottom:7px;border-bottom:1px solid #3f3025;margin-bottom:8px}.accAxisHead b{font-size:9px;letter-spacing:.16em;color:#d0a35d}.accAxisHead span{font-size:7px;letter-spacing:.09em;color:#75695b}.accChoices{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:7px}.accChoice{position:relative;border:1px solid #4e3a2a;background:#100e0c;border-radius:4px;overflow:hidden;color:#e7dbcb;cursor:pointer;text-align:left;padding:0;min-height:105px;transition:.14s ease}.accChoice:hover{transform:translateY(-1px);border-color:#8a673f}.accChoice img{width:100%;height:76px;object-fit:cover;display:block;filter:saturate(.8) contrast(1.03);border-bottom:1px solid #443225}.accChoice.person img{object-position:center 24%}.accChoice b{display:block;padding:7px 7px 8px;font-family:Georgia,serif;font-size:11px;line-height:1.05}.accChoice i{position:absolute;top:5px;left:5px;background:#0b0907d9;border:1px solid #6d5438;color:#d2b17b;padding:3px 4px;font:800 6px/1 ui-monospace,monospace;font-style:normal;letter-spacing:.08em}.accChoice.selected{border:2px solid #b23d34;background:#23110f;box-shadow:0 0 0 1px rgba(178,61,52,.18),0 7px 18px rgba(0,0,0,.26)}.accChoice.selected:after{content:"ELEGIDO";position:absolute;right:-16px;top:8px;transform:rotate(38deg);background:#8c2823;color:#f9e8d6;padding:3px 18px;font-size:5px;letter-spacing:.08em;font-weight:950}.accMotive{margin-top:17px;border:1px solid #72573a;background:linear-gradient(135deg,#d2bd99,#b49770);color:#251b12;display:grid;grid-template-columns:165px 1fr}.accMotiveLabel{padding:14px;border-right:1px solid #866b4d}.accMotiveLabel small{display:block;color:#752923;font-size:7px;letter-spacing:.13em;font-weight:950}.accMotiveLabel b{display:block;font:700 18px Georgia,serif;margin:4px 0}.accMotiveLabel p{font-size:9px;line-height:1.45;color:#59442f;margin:7px 0 0}.accMotive textarea{border:0!important;border-radius:0!important;background:repeating-linear-gradient(180deg,transparent 0 27px,rgba(72,50,30,.14) 27px 28px)!important;color:#2b2118!important;min-height:128px!important;padding:14px 15px!important;font-family:Georgia,serif!important;line-height:28px!important;outline:none}.accSealRow{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:15px;padding-top:13px;border-top:1px solid #443127}.accReady{font-size:9px;letter-spacing:.08em;color:#8b7b68}.accReady strong{color:#d9b370}.accLockButton{background:linear-gradient(#a52d28,#6d1a18)!important;border-color:#c1443b!important;padding:12px 17px!important;letter-spacing:.08em}.accLockButton:disabled{opacity:.38}.accLockedCase{border:1px solid #784039;background:linear-gradient(145deg,#d2bd99,#b4946e);color:#251a13;padding:17px;position:relative;overflow:hidden}.accLockedCase:after{content:"BLOQUEADA";position:absolute;right:-10px;top:16px;border:3px solid rgba(125,35,31,.38);color:rgba(125,35,31,.48);padding:5px 9px;transform:rotate(-6deg);font-size:11px;font-weight:950;letter-spacing:.12em}.accLockedCase small{display:block;color:#70241f;font-size:8px;letter-spacing:.15em;font-weight:950}.accLockedCase h3{font:700 24px Georgia,serif;margin:5px 0 12px}.accLockedGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.accLockedItem{border:1px solid rgba(85,59,37,.3);background:rgba(255,255,255,.12);padding:9px}.accLockedItem span{display:block;font-size:7px;letter-spacing:.1em;color:#6a5239}.accLockedItem b{display:block;margin-top:4px;font-family:Georgia,serif}.accLockedMotive{margin-top:9px;border-left:3px solid #7a2923;background:rgba(255,255,255,.1);padding:9px;font-size:11px;line-height:1.5}.accRevealRow{margin-top:12px;display:flex;justify-content:flex-end}.accWaiting{border:1px dashed #5b4430;padding:14px;color:#9c8b78;font-size:11px;line-height:1.5}.accWaiting b{color:#d0ab70}
@media(max-width:980px){.accChoices{grid-template-columns:repeat(3,1fr)}.accChoice img{height:92px}}
@media(max-width:620px){.accHero{padding:16px}.accBody{padding:14px}.accProgress{grid-template-columns:repeat(2,1fr)}.accChoices{grid-template-columns:repeat(2,1fr)}.accChoice img{height:104px}.accMotive{grid-template-columns:1fr}.accMotiveLabel{border-right:0;border-bottom:1px solid #866b4d}.accSealRow{display:grid}.accLockButton{width:100%}.accLockedGrid{grid-template-columns:1fr}}
'''
anchor='/* P2.12D.8 · DIRECTOR + BITÁCORA */'
if anchor not in s: raise SystemExit('D8 marker missing')
s=s.replace(anchor,css+'\n'+anchor,1)

old='''      <section id="accusationPanel" class="panel hidden"><h2 style="margin-top:0">Acusación final</h2><div id="accusationBody"></div></section>'''
new='''      <section id="accusationPanel" class="panel accusationCinematic hidden"><div class="accHero"><div class="accKicker">EXPEDIENTES · CASO 001 · CIERRE DE INVESTIGACIÓN</div><h2>Acusación final</h2><p>El equipo debe sostener una reconstrucción completa. Elegí una Persona, una Escena y un Objeto; después escribí el Motivo que conecta la secuencia.</p></div><div id="accusationBody" class="accBody"></div></section>'''
if old not in s: raise SystemExit('accusation html anchor missing')
s=s.replace(old,new,1)

state='let privateInfoHidden=false;'
if state not in s: raise SystemExit('private state anchor missing')
s=s.replace(state,state+"\nlet accDraft={suspect:null,location:null,object:null,motive:''};",1)

helpers=r'''function accusationChoice(axis,index,label,img,kind){const selected=Number(accDraft[axis])===Number(index);const code=axis==='suspect'?`P${index+1}`:axis==='location'?`L${index+1}`:`O${index+1}`;return `<button type="button" class="accChoice ${kind} ${selected?'selected':''}" data-acc-axis="${axis}" data-acc-index="${index}"><img src="${esc(img)}" alt="${esc(label)}"><i>${esc(code)}</i><b>${esc(label)}</b></button>`}
function accusationAxis(title,hint,axis,labels,images,kind){return `<section class="accAxis"><div class="accAxisHead"><b>${esc(title)}</b><span>${esc(hint)}</span></div><div class="accChoices">${labels.map((label,i)=>accusationChoice(axis,i,label,images[i],kind)).join('')}</div></section>`}
function bindAccusationDraft(){document.querySelectorAll('[data-acc-axis]').forEach(b=>b.onclick=()=>{const axis=b.dataset.accAxis,index=Number(b.dataset.accIndex);accDraft[axis]=index;renderAccusation()});const motive=$('#accM');if(motive)motive.oninput=()=>{accDraft.motive=motive.value}}
'''

pat=re.compile(r'function renderAccusation\(\)\{.*?\}\nfunction renderSolution\(\)\{',re.S)
m=pat.search(s)
if not m: raise SystemExit('renderAccusation anchor missing')
new_render=r'''function renderAccusation(){const state=view?.public_state||{},stage=Number(state.stage||1),locked=!!state.accusation_locked,acc=latestEvent('accusation_locked'),panel=$('#accusationPanel');panel.classList.toggle('hidden',stage<3&&view?.room?.status!=='finished');if(panel.classList.contains('hidden'))return;if(locked||acc){const p=acc?.payload||{};$('#accusationBody').innerHTML=`<article class="accLockedCase"><small>ACTA DE ACUSACIÓN · REGISTRO DEFINITIVO</small><h3>La hipótesis del equipo quedó sellada</h3><div class="accLockedGrid"><div class="accLockedItem"><span>PERSONA</span><b>${esc(p.suspect_name||'—')}</b></div><div class="accLockedItem"><span>ESCENA</span><b>${esc(p.location_name||'—')}</b></div><div class="accLockedItem"><span>OBJETO</span><b>${esc(p.object_name||'—')}</b></div></div>${p.motive_text?`<div class="accLockedMotive"><b>MOTIVO / HIPÓTESIS</b><br>${esc(p.motive_text)}</div>`:''}</article>${view?.is_host&&view?.room?.status==='active'?'<div class="accRevealRow"><button id="revealSolution" class="btn good">REVELAR RECONSTRUCCIÓN</button></div>':''}`;$('#revealSolution')?.addEventListener('click',()=>doAction(async()=>{await adapter.action('finish');await refresh(true)},'Solución revelada.'));return}if(!view?.is_host){$('#accusationBody').innerHTML='<div class="accWaiting"><b>ACUSACIÓN EN PREPARACIÓN</b><br>El anfitrión registrará la hipótesis consensuada por el equipo cuando estén listos.</div>';return}const chosen=[accDraft.suspect,accDraft.location,accDraft.object].filter(v=>Number.isInteger(Number(v))).length;$('#accusationBody').innerHTML=`<div class="accProgress"><span class="${accDraft.suspect!==null?'done':''}">01 · PERSONA</span><span class="${accDraft.location!==null?'done':''}">02 · ESCENA</span><span class="${accDraft.object!==null?'done':''}">03 · OBJETO</span><span class="${String(accDraft.motive||'').trim()?'done':''}">04 · MOTIVO</span></div>${accusationAxis('01 · PERSONA','¿QUIÉN?', 'suspect',P2_LABELS.characters,REV01_PORTRAITS,'person')}${accusationAxis('02 · ESCENA','¿DÓNDE?', 'location',P2_LABELS.locations,REV01_LOCATION_IMAGES,'location')}${accusationAxis('03 · OBJETO','¿QUÉ ELEMENTO?', 'object',P2_LABELS.objects,REV01_OBJECT_IMAGES,'object')}<div class="accMotive"><div class="accMotiveLabel"><small>04 · MOTIVO</small><b>Hipótesis causal</b><p>Explicá por qué creen que ocurrió y qué evidencia conecta a la persona, la escena y el objeto.</p></div><textarea id="accM" maxlength="700" placeholder="Escriban la teoría final del equipo…">${esc(accDraft.motive||'')}</textarea></div><div class="accSealRow"><div class="accReady"><strong>${chosen}/3</strong> ejes obligatorios seleccionados${String(accDraft.motive||'').trim()?' · motivo escrito':''}</div><button id="lockAcc" class="btn primary accLockButton" ${chosen<3?'disabled':''}>SELLAR ACUSACIÓN</button></div>`;bindAccusationDraft();$('#lockAcc').onclick=()=>{if(chosen<3){toast('Completá Persona + Escena + Objeto.',true);return}doAction(async()=>{await adapter.action('accuse',{suspect_index:Number(accDraft.suspect),location_index:Number(accDraft.location),object_index:Number(accDraft.object),motive_text:String(accDraft.motive||'')});await refresh(true)},'Acusación bloqueada.')}}
'''
s=s[:m.start()]+helpers+new_render+'function renderSolution(){'+s[m.end():]

p.write_text(s)
print('P2.12D.9 patch complete')
